          assert.equal(row.children[2].children[1].disabled, Boolean(archived));
          assert.equal(row.children[2].children[2].disabled, Boolean(archived));
          assert.equal(row.find((node) => node.tag === 'select').disabled, Boolean(archived));
        }
      }
    }
  }
